import time
import schedule
import traceback
import datetime

from modules.system_monitor import save_report
from modules.decision_logger import log_decision
from modules.income_scan import create_report
from modules.data_collector import collect_data
from modules.decision_engine import create_decision_report
from modules.opportunity_researcher import save_opportunities



def safe_run(task_name, function):

    try:

        function()

        log_decision(
            task_name,
            "Completed",
            "Task executed successfully"
        )


    except Exception as e:

        log_decision(
            task_name,
            "Failed",
            str(e)
        )

        print(task_name, "failed")

        traceback.print_exc()



def run_system_check():

    safe_run(
        "System Monitor",
        save_report
    )



def run_income_scan():

    safe_run(
        "Income Scanner",
        create_report
    )



def run_data_collection():

    safe_run(
        "Data Collector",
        collect_data
    )



def run_opportunity_research():

    safe_run(
        "Opportunity Researcher",
        save_opportunities
    )



def run_decision_engine():

    safe_run(
        "Decision Engine",
        create_decision_report
    )



def startup():

    print("==============================")
    print("AI System Agent Started")
    print(datetime.datetime.now())
    print("==============================")


    run_system_check()
    run_income_scan()
    run_data_collection()
    run_opportunity_research()
    run_decision_engine()



def main():

    startup()


    schedule.every(30).minutes.do(
        run_system_check
    )


    schedule.every(1).hour.do(
        run_income_scan
    )


    schedule.every(15).minutes.do(
        run_data_collection
    )


    schedule.every(2).hours.do(
        run_opportunity_research
    )


    schedule.every(2).hours.do(
        run_decision_engine
    )


    while True:

        schedule.run_pending()

        time.sleep(1)



if __name__ == "__main__":

    main()
